SELECT * FROM `flyways.asa_positions.asa_positions` WHERE DATE(position_timestamp) = '2026-09-16' AND common.position_timestamp >= TIMESTAMP('2026-09-16 05:00:00') AND common.position_timestamp < TIMESTAMP('2026-09-16 06:00:00') AND common.latitude BETWEEN 48.6 AND 49.8 AND common.longitude BETWEEN -123.775 AND -122.575
